-- Tenancy's own rows. Each project's org and its name there, held
-- lower-case and unique per org: what `/<org>/<project>` resolves through.
-- Each agent's org and the user who sponsors it, null for agents enrolled
-- before tenancy. An org's suspension by the instance admin, generated by
-- better-auth 1.7.7's compileMigrations from the organization plugin's
-- organization.additionalFields, and held equal to them by [ba.schema].
-- Expand-only: a new table, its index and nullable or defaulted columns.
CREATE TABLE projects (
  id         TEXT PRIMARY KEY,
  org_id     TEXT NOT NULL,
  name       TEXT NOT NULL,
  created_at INTEGER NOT NULL
);

CREATE UNIQUE INDEX projects_by_org_name ON projects (org_id, name);

ALTER TABLE agents ADD COLUMN org_id TEXT;

ALTER TABLE agents ADD COLUMN sponsor_user TEXT;

alter table "organization" add column "suspended" integer default 0;
